public with sharing class DetailReader {
  public static String observe(List<Id> ids) {
    Id pub=ids[0], priv=ids[1];
    return 'publicMaster='+[SELECT Id FROM PublicMaster__c WHERE Id=:pub WITH SYSTEM_MODE].size()
      +';publicDetail='+[SELECT Id FROM PublicDetail__c WHERE Master__c=:pub WITH SYSTEM_MODE].size()
      +';privateMaster='+[SELECT Id FROM PrivateMaster__c WHERE Id=:priv WITH SYSTEM_MODE].size()
      +';privateDetail='+[SELECT Id FROM PrivateDetail__c WHERE Master__c=:priv WITH SYSTEM_MODE].size()
      +';withoutSharing='+DetailSeed.privateCount(priv);
  }
}

