public without sharing class DetailSeed {
  public static List<Id> seed() {
    PublicMaster__c pub = new PublicMaster__c(Name='Public'); insert as system pub;
    PrivateMaster__c priv = new PrivateMaster__c(Name='Private'); insert as system priv;
    insert as system new PublicDetail__c(Name='Public detail', Master__c=pub.Id);
    insert as system new PrivateDetail__c(Name='Private detail', Master__c=priv.Id, PublicLink__c=pub.Id);
    return new List<Id>{pub.Id, priv.Id};
  }
  public static Integer privateCount(Id id) {
    return [SELECT Id FROM PrivateDetail__c WHERE Master__c=:id WITH SYSTEM_MODE].size();
  }
}

